"""Exact search: do count / level dominance (naive above every threshold rule)
survive mixed gain laws?  Window-sum screen over all rules, then direct checks."""
import sys, itertools, random, time
from fractions import Fraction as Q

WT = r"C:\Users\patri\AppData\Local\Temp\claude\C--Users-patri-OneDrive-Documents-GitHub-Spiral\af5af8c1-0184-44ad-ab52-2aae8f4d54ac\scratchpad\wt_mix"
sys.path.insert(0, WT + r"\src")
from spiral_ln.evaluation_feedback_multigen import (drift_kernel, kernel_iterates, naive_threshold,
                                                    decaying_gain_schedule, drift_levels)

H = 30


def mixed_window_sums(kernel, f, items):
    out = {}
    for (c, i), entries in kernel.items():
        by_count = {}
        for y, p in entries[1:]:
            by_count.setdefault(y[0], []).append((y, p))
        running, sums = Q(0), []
        for J in range(c + 1, items + 1):
            for y, p in by_count.get(J, []):
                running += p * (f[y] - f[(c, i)])
            sums.append(running)
        out[(c, i)] = sums
    return out


def objectives(items, levels):
    top = len(levels) - 1
    fs = {"count": lambda x: Q(x[0]), "level": lambda x: levels[x[1]]}
    for m in range(1, items + 1):
        fs[f"hit>={m}"] = (lambda x, m=m: Q(int(x[0] >= m)))
    for ell in range(1, top + 1):
        fs[f"lvl>={ell}"] = (lambda x, ell=ell: Q(int(x[1] >= ell)))
    return fs


LATTICES = {
    "quarter_half_jump": (Q(1, 4), Q(3, 4), Q(1)),
    "eighth_seven_eighths_one": (Q(1, 8), Q(7, 8), Q(1)),
    "eighth_seven_eighths": (Q(1, 8), Q(7, 8)),
    "std_eighth": drift_levels(Q(1, 4), Q(1, 8)),
    "quarter_steps": (Q(1, 4), Q(1, 2), Q(3, 4), Q(1)),
    "half_jump_twice": (Q(1, 4), Q(1, 4), Q(3, 4), Q(3, 4), Q(1)),
}
LAWS = {}
for q in (Q(1, 4), Q(1, 2), Q(3, 4)):
    LAWS[f"two_point_q={q}"] = {0: 1 - q, 1: q}
    LAWS[f"zero_or_two_q={q}"] = {0: 1 - q, 2: q}

t0 = time.time()
negatives = []
configs = 0
for items in (2, 3, 4, 5, 6):
    for K in (1, 2):
        for lname, levels in LATTICES.items():
            for law_name, law in LAWS.items():
                configs += 1
                kernel = drift_kernel(items, K, levels, law, naive_threshold(items))
                for fname, f in objectives(items, levels).items():
                    u = kernel_iterates(kernel, f, H)
                    for k in range(H + 1):
                        for (c, i), sums in mixed_window_sums(kernel, u[k], items).items():
                            for idx, w in enumerate(sums):
                                if w < 0:
                                    negatives.append((items, K, lname, law_name, fname, k, (c, i), c + 1 + idx, w))
print("configs", configs, "negatives", len(negatives), "time", round(time.time() - t0, 1))
seen = set()
for neg in negatives:
    key = neg[:5]
    if key in seen:
        continue
    seen.add(key)
    print(neg[:8], float(neg[8]))
    if len(seen) > 60:
        break
# summary by objective
from collections import Counter
print(Counter(n[4] for n in negatives))
print(Counter((n[0], n[1]) for n in negatives))
print(Counter(n[3] for n in negatives))
print(Counter(n[2] for n in negatives))

