"""Direct rule-by-rule comparisons, decaying schedule, proof-structure probes."""
import sys, itertools, random, time
from fractions import Fraction as Q
from collections import Counter

WT = r"C:\Users\patri\AppData\Local\Temp\claude\C--Users-patri-OneDrive-Documents-GitHub-Spiral\af5af8c1-0184-44ad-ab52-2aae8f4d54ac\scratchpad\wt_mix"
sys.path.insert(0, WT + r"\src")
from spiral_ln.evaluation_feedback_multigen import (drift_kernel, kernel_iterates, naive_threshold,
                                                    decaying_gain_schedule, drift_levels, best_of_pmf)

random.seed(20261013)


def objectives(items, levels):
    top = len(levels) - 1
    fs = {"count": lambda x: Q(x[0]), "level": lambda x: levels[x[1]]}
    for m in range(1, items + 1):
        fs[f"hit>={m}"] = (lambda x, m=m: Q(int(x[0] >= m)))
    for ell in range(1, top + 1):
        fs[f"lvl>={ell}"] = (lambda x, ell=ell: Q(int(x[1] >= ell)))
    return fs


def all_rules(items):
    return list(itertools.product(*[range(items - c + 1) for c in range(items + 1)]))


def random_rules(items, count):
    return [tuple(random.randint(0, items - c) for c in range(items + 1)) for _ in range(count)]


LATTICES = {
    "quarter_half_jump": (Q(1, 4), Q(3, 4), Q(1)),
    "eighth_seven_eighths_one": (Q(1, 8), Q(7, 8), Q(1)),
    "eighth_seven_eighths": (Q(1, 8), Q(7, 8)),
    "quarter_steps": (Q(1, 4), Q(1, 2), Q(3, 4), Q(1)),
}
LAWS = {}
for q in (Q(1, 4), Q(1, 2), Q(3, 4)):
    LAWS[f"two_point_q={q}"] = {0: 1 - q, 1: q}
LAWS["zero_or_two_half"] = {0: Q(1, 2), 2: Q(1, 2)}

# ---- Part 1: direct comparisons, constant laws ----
t0 = time.time()
H = 20
violations = []
rules_checked = 0
for items in (2, 3, 4, 5, 6):
    rules = all_rules(items) if items <= 4 else random_rules(items, 60 if items == 5 else 30)
    for K in (1, 2):
        for lname, levels in LATTICES.items():
            for law_name, law in LAWS.items():
                naive = drift_kernel(items, K, levels, law, naive_threshold(items))
                fs = objectives(items, levels)
                u = {fname: kernel_iterates(naive, f, H) for fname, f in fs.items()}
                for rule in rules:
                    if all(t == 0 for t in rule):
                        continue
                    rules_checked += 1
                    gated = drift_kernel(items, K, levels, law, rule)
                    for fname, f in fs.items():
                        w = kernel_iterates(gated, f, H)
                        for k in range(H + 1):
                            for x in naive:
                                if w[k][x] > u[fname][k][x]:
                                    violations.append((items, K, lname, law_name, rule, fname, k, x, w[k][x], u[fname][k][x]))
print("part1 rules checked", rules_checked, "violations", len(violations), "time", round(time.time() - t0, 1))
for v in violations[:20]:
    print(v)

# ---- Part 2: decaying schedule, window screen + direct rules (forward) ----
t0 = time.time()
G_MAX = 30
neg = []
direct_viol = []
for items in (2, 3, 4, 5):
    rules = all_rules(items) if items <= 4 else random_rules(items, 40)
    for K in (1, 2):
        for lname, levels in LATTICES.items():
            for q0 in (Q(1, 4), Q(1, 2), Q(3, 4)):
                schedule = decaying_gain_schedule(G_MAX, q0, Q(3, 4))
                kernels = [drift_kernel(items, K, levels, law, naive_threshold(items)) for law in schedule]
                fs = objectives(items, levels)
                states = list(kernels[0])
                for fname, f in fs.items():
                    # window screen: for each horizon G, v_G = f, v_g = P_{g+1} v_{g+1}
                    for G in range(1, G_MAX + 1):
                        v = {x: Q(f(x)) for x in states}
                        for g in range(G - 1, -1, -1):
                            kern = kernels[g]
                            # window sums of v with kernel g's landings
                            for (c, i), entries in kern.items():
                                running = Q(0)
                                by_count = {}
                                for y, p in entries[1:]:
                                    by_count.setdefault(y[0], []).append((y, p))
                                for J in range(c + 1, items + 1):
                                    for y, p in by_count.get(J, []):
                                        running += p * (v[y] - v[(c, i)])
                                    if running < 0:
                                        neg.append((items, K, lname, str(q0), fname, G, g, (c, i), J, running))
                            v = {x: sum((p * v[y] for y, p in entries), Q(0)) for x, entries in kern.items()}
                # direct: forward distributions from every start state for all rules, horizons <= 20
                Hd = 20
                naive_vals = {}
                for x0 in states:
                    dist = {x0: Q(1)}
                    naive_vals[x0] = []
                    for g in range(Hd):
                        kern = kernels[g]
                        nxt = {}
                        for x, mass in dist.items():
                            for y, p in kern[x]:
                                if p:
                                    nxt[y] = nxt.get(y, Q(0)) + mass * p
                        dist = nxt
                        naive_vals[x0].append({fname: sum((mass * f(x) for x, mass in dist.items()), Q(0)) for fname, f in fs.items()})
                for rule in rules:
                    if all(t == 0 for t in rule):
                        continue
                    gk = [drift_kernel(items, K, levels, law, rule) for law in schedule[:Hd]]
                    for x0 in states:
                        dist = {x0: Q(1)}
                        for g in range(Hd):
                            nxt = {}
                            for x, mass in dist.items():
                                for y, p in gk[g][x]:
                                    if p:
                                        nxt[y] = nxt.get(y, Q(0)) + mass * p
                            dist = nxt
                            for fname, f in fs.items():
                                val = sum((mass * f(x) for x, mass in dist.items()), Q(0))
                                if val > naive_vals[x0][g][fname]:
                                    direct_viol.append((items, K, lname, str(q0), rule, fname, g + 1, x0, val, naive_vals[x0][g][fname]))
print("part2 decaying: window negatives", len(neg), "direct violations", len(direct_viol), "time", round(time.time() - t0, 1))
for v in neg[:10]:
    print(v)
for v in direct_viol[:10]:
    print(v)

# ---- Part 3: proof-structure probes on the two-point law ----
t0 = time.time()
H = 16
g_not_monotone = []
prefix_avg_above_full = []
L2_fail, L3_fail, L1_fail = [], [], []
posterior_mono_fail = []
for items in (3, 4, 5, 6, 8):
    for K in (1, 2, 3):
        for lname, levels in {**LATTICES, "std_eighth": drift_levels(Q(1, 4), Q(1, 8))}.items():
            top = len(levels) - 1
            for law_name, law in LAWS.items():
                kernel = drift_kernel(items, K, levels, law, naive_threshold(items))
                states = list(kernel)
                for m in range(2, items + 1):
                    u = kernel_iterates(kernel, lambda x, m=m: Q(int(x[0] >= m)), H)
                    s = [{x: 1 - u[k][x] for x in states} for k in range(H + 1)]
                    for k in range(H + 1):
                        for (c, i) in states:
                            if c >= m:
                                continue
                            entries = kernel[(c, i)]
                            by_count = {}
                            for y, p in entries[1:]:
                                by_count.setdefault(y[0], []).append((y, p))
                            # g_k(J) = E[s_k(landing) | M = J], pi(J) = sum p
                            gs, pis = [], []
                            for J in range(c + 1, m):
                                lst = by_count.get(J, [])
                                piJ = sum((p for _, p in lst), Q(0))
                                if piJ:
                                    gs.append(sum((p * s[k][y] for y, p in lst), Q(0)) / piJ)
                                    pis.append(piJ)
                            if any(b < a for a, b in zip(gs, gs[1:])):
                                g_not_monotone.append((items, K, lname, law_name, m, k, (c, i), [float(x) for x in gs]))
                            if gs:
                                full = sum(p * g for p, g in zip(pis, gs)) / sum(pis)
                                run_p, run_g = Q(0), Q(0)
                                for p, g in zip(pis, gs):
                                    run_p += p
                                    run_g += p * g
                                    if run_g / run_p > full:
                                        prefix_avg_above_full.append((items, K, lname, law_name, m, k, (c, i)))
                                        break
                            if c + 1 < m and s[k][(c, i)] > s[k][(c + 1, i)]:
                                L2_fail.append((items, K, lname, law_name, m, k, (c, i)))
                            if i < top and s[k][(c, i + 1)] > s[k][(c, i)]:
                                L3_fail.append((items, K, lname, law_name, m, k, (c, i)))
                            if k >= 1:
                                death = 1 - sum(p for y, p in entries if y[0] < m) - (entries[0][1] if False else 0)
                                # death = P(M >= m) from level i: 1 - (stay + landings below m)
                                death = 1 - entries[0][1] - sum((p for y, p in entries[1:] if y[0] < m), Q(0))
                                if s[k][(c, i)] > (1 - death) * s[k - 1][(c, i)]:
                                    L1_fail.append((items, K, lname, law_name, m, k, (c, i)))
print("part3 time", round(time.time() - t0, 1))
print("g_k(J) not monotone in J:", len(g_not_monotone))
for v in g_not_monotone[:8]:
    print(v)
print("prefix average above full average:", len(prefix_avg_above_full))
for v in prefix_avg_above_full[:8]:
    print(v)
print("L1 fail", len(L1_fail), "L2 fail", len(L2_fail), "L3 fail", len(L3_fail))
for v in L2_fail[:5]:
    print("L2", v)
for v in L3_fail[:5]:
    print("L3", v)

